cat > src/lib/email.ts <<'EOF'
import { getPostmark } from "@/lib/postmark";

type Recipient = { email: string; name: string };

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
}

function appUrl(): string {
  return process.env.APP_URL ?? "http://localhost:3000";
}

async function send(to: string, subject: string, text: string, html: string) {
  const from = process.env.POSTMARK_FROM_EMAIL;
  if (!from) throw new Error("POSTMARK_FROM_EMAIL is not set");
  await getPostmark().sendEmail({
    From: from,
    To: to,
    Subject: subject,
    TextBody: text,
    HtmlBody: html,
    MessageStream: process.env.POSTMARK_MESSAGE_STREAM ?? "outbound",
  });
}

export async function sendWelcomeEmail(user: Recipient) {
  const name = escapeHtml(user.name);
  await send(
    user.email,
    "Welcome to Notely",
    `Hi ${user.name},\n\nThanks for signing up for Notely. Open ${appUrl()} to start taking notes.`,
    `<p>Hi ${name},</p><p>Thanks for signing up for Notely. <a href="${appUrl()}">Open Notely</a> to start taking notes.</p>`,
  );
}

export async function sendPasswordResetEmail(user: Recipient, token: string) {
  const url = `${appUrl()}/reset-password?token=${encodeURIComponent(token)}`;
  await send(
    user.email,
    "Reset your Notely password",
    `Hi ${user.name},\n\nReset your password: ${url}\n\nThis link expires in 1 hour. If you didn't request it, ignore this email.`,
    `<p>Hi ${escapeHtml(user.name)},</p><p><a href="${url}">Reset your password</a>. This link expires in 1 hour.</p><p>If you didn't request it, ignore this email.</p>`,
  );
}
EOF
